22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        ScopeSelector.validate(eval, query);
83	        return eval;
84	    }
85	
86	    Evaluator parseSelectorGroup() {
87	        // SelectorGroup. Into an Or if > 1 Selector
88	        Evaluator left = parseSelector();
89	        while (tq.matchChomp(',')) {
90	            Evaluator right = parseSelector();
91	            left = or(left, right);
92	        }
93	        return left;
94	    }
95	
96	    Evaluator parseSelector() {
97	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
98	        tq.consumeWhitespace();
99	
100	        Evaluator left;
101	        if (tq.matchesAny(Combinators)) {
102	            // e.g. query is "> div"; left side is root element
103	            left = new StructuralEvaluator.Root();
104	        } else {
105	            left = parseSimpleSequence();
106	        }
107	
108	        while (true) {
109	            char combinator = 0;
110	            if (tq.consumeWhitespace())
111	                combinator = ' ';            // maybe descendant?
112	            if (tq.matchesAny(Combinators)) // no, explicit
113	                combinator = tq.consume();
114	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
115	                break;
116	
117	            if (combinator != 0) {
118	                tq.consumeWhitespace();
119	                if (tq.matchesAny(Combinators) || tq.matchesAny(SequenceEnders) || tq.isEmpty())
120	                    // a dangling combinator (e.g. "div >", ":has(>)", or ":has(p, +)") is not a valid selector
121	                    throw new Selector.SelectorParseException(
122	                        "Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
123	                Evaluator right = parseSimpleSequence();
124	                left = combinator(left, combinator, right);
125	            } else {
126	                break;
127	            }
128	        }
129	        return left;
130	    }
131	
132	    Evaluator parseSimpleSequence() {
133	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
134	        Evaluator left = null;
135	        tq.consumeWhitespace();
136	
137	        // one optional type selector
138	        if (tq.matchesWord() || tq.matches("*|"))
139	            left = byTag();
140	        else if (tq.matchChomp('*'))
141	            left = new Evaluator.AllElements();
142	
143	        // zero or more subclasses (#, ., [)
144	        while(true) {
145	            Evaluator right = parseSubclass();
146	            if (right != null) {
147	                left = and(left, right);
148	            }
149	            else break; // no more simple tokens
150	        }
151	
152	        if (left == null)
153	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
154	        return left;
155	    }
156	
157	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
158	        switch (combinator) {
159	            case '>':
160	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
161	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
162	                run.add(right);
163	                return run;
164	            case ' ':
165	                return and(new StructuralEvaluator.Ancestor(left), right);
166	            case '+':
167	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
168	            case '~':
169	                return and(new StructuralEvaluator.PreviousSibling(left), right);
170	            default:
171	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
172	        }
173	    }
174	
175	    @Nullable Evaluator parseSubclass() {
176	        //  Subclass: ID | Class | Attribute | Pseudo
177	        if      (tq.matchChomp('#'))    return byId();
178	        else if (tq.matchChomp('.'))    return byClass();
179	        else if (tq.matches('['))       return byAttribute();
180	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
181	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
182	        else                            return null;
183	    }
184	
185	    /** Merge two evals into an Or. */
186	    static Evaluator or(Evaluator left, Evaluator right) {
187	        if (left instanceof CombiningEvaluator.Or) {
188	            ((CombiningEvaluator.Or) left).add(right);
189	            return left;
190	        }
191	        return new CombiningEvaluator.Or(left, right);
192	    }
193	
194	    /** Merge two evals into an And. */
195	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
196	        if (left == null) return right;
197	        if (left instanceof CombiningEvaluator.And) {
198	            ((CombiningEvaluator.And) left).add(right);
199	            return left;
200	        }
201	        return new CombiningEvaluator.And(left, right);
202	    }
203	
204	    private Evaluator parsePseudoSelector() {
205	        final String pseudo = tq.consumeCssIdentifier();
206	        switch (pseudo) {
207	            case "lt":
208	                return new Evaluator.IndexLessThan(consumeIndex());
209	            case "gt":
210	                return new Evaluator.IndexGreaterThan(consumeIndex());
211	            case "eq":
212	                return new Evaluator.IndexEquals(consumeIndex());
213	            case "has":
214	                return has();
215	            case "is":
216	                return is();
217	            case "contains":
218	                return contains(false);
219	            case "containsOwn":
220	                return contains(true);
221	            case "containsWholeText":
222	                return containsWholeText(false);
223	            case "containsWholeOwnText":
224	                return containsWholeText(true);
225	            case "containsData":
226	                return containsData();
227	            case "matches":
228	                return matches(false);
229	            case "matchesOwn":
230	                return matches(true);
231	            case "matchesWholeText":
232	                return matchesWholeText(false);
233	            case "matchesWholeOwnText":
234	                return matchesWholeText(true);
235	            case "not":
236	                return not();
237	            case "nth-child":
238	                return cssNthChild(false, false);
239	            case "nth-last-child":
240	                return cssNthChild(true, false);
241	            case "nth-of-type":
242	                return cssNthChild(false, true);
243	            case "nth-last-of-type":
244	                return cssNthChild(true, true);
245	            case "first-child":
246	                return new Evaluator.IsFirstChild();
247	            case "last-child":
248	                return new Evaluator.IsLastChild();
249	            case "first-of-type":
250	                return new Evaluator.IsFirstOfType();
251	            case "last-of-type":
252	                return new Evaluator.IsLastOfType();
253	            case "only-child":
254	                return new Evaluator.IsOnlyChild();
255	            case "only-of-type":
256	                return new Evaluator.IsOnlyOfType();
257	            case "empty":
258	                return new Evaluator.IsEmpty();
259	            case "blank":
260	                return new NodeEvaluator.BlankValue();
261	            case "root":
262	                return new Evaluator.IsRoot();
263	            case "scope":
264	                return new Evaluator.IsScope();
265	            case "matchText": {
266	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
267	                Evaluator.MatchText matchText = new Evaluator.MatchText();
268	                return matchText;
269	            }
270	            default:
271	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
272	        }
273	    }
