497	    // pseudo selector :has(el)
498	    private Evaluator has() {
499	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
500	    }
501	
502	    // pseudo selector :is()
503	    private Evaluator is() {
504	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
505	    }
506	
507	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
508	        Validate.isTrue(tq.matchChomp('('), err);
509	        Evaluator eval = parseSelectorGroup();
510	        Validate.isTrue(tq.matchChomp(')'), err);
511	        return func.apply(eval);
512	    }
