36	    boolean memoMatches(final Element root, final Node node) {
37	        Map<Node, Map<Node, Boolean>> rootMemo = threadMemo.get();
38	        Map<Node, Boolean> memo = rootMemo.computeIfAbsent(root, r -> new WeakHashMap<>());
39	        return memo.computeIfAbsent(node, test -> evaluator.matches(root, test));
40	    }
41	
42	    @Override protected void reset() {
43	        threadMemo.remove();
44	        evaluator.reset();
45	        super.reset();
46	    }
47	
48	    @Override
49	    public boolean matches(Element root, Element element) {
50	        return evaluateMatch(root, element);
51	    }
52	
53	    @Override
54	    boolean matches(Element root, LeafNode leafNode) {
55	        return evaluateMatch(root, leafNode);
56	    }
57	
58	    abstract boolean evaluateMatch(Element root, Node node);
59	
60	    static class Root extends Evaluator {
61	        @Override
62	        public boolean matches(Element root, Element element) {
63	            return root == element;
64	        }
65	
66	        @Override protected int cost() {
67	            return 1;
68	        }
69	
70	        @Override public String toString() {
71	            return ">";
72	        }
73	    }
74	
75	    /**
76	     * Implements the {@code :has(relative-selector-list)} structural pseudo-class. The current candidate element is the
77	     * <b>anchor</b>; each comma-separated branch is evaluated <i>relative to that anchor</i>, and the anchor never
78	     * drifts to its own ancestors or siblings while a branch is tested:
79	     * <ul>
80	     *   <li>a branch with no leading combinator matches only within the anchor's descendants;</li>
81	     *   <li>a branch beginning with {@code >} (encoded as an {@link ImmediateParentRun} from the synthetic {@link Root})
82	     *       is confined to direct element children and below;</li>
83	     *   <li>a branch beginning with {@code +} or {@code ~} (an immediate/general sibling evaluator whose left side is
84	     *       the synthetic {@link Root}) is evaluated against the anchor's following element siblings and their
85	     *       descendants only; non-element nodes never act as siblings.</li>
86	     * </ul>
87	     * The parsed evaluator tree is left intact; the axis of each branch is derived from whether its leading combinator
88	     * references the synthetic {@link Root}. Branches are ORed here, but the collector de-duplicates and orders results.
89	     */
90	    static class Has extends StructuralEvaluator {
91	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
92	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
93	        // the element here is just a placeholder so this can be final - gets set in restart()
94	
95	        private final Evaluator[] branches; // each comma-separated relative branch
96	        private final char[] axes;          // axis per branch: 0 = descendants, '+' / '~' = following element siblings
97	        private final boolean[] deep;       // sibling branches that chain a further combinator and so must search subtrees
98	        private final boolean[] selfScope;  // descendant-axis branches whose :scope may match the anchor itself
99	
100	        public Has(Evaluator evaluator) {
101	            super(evaluator);
102	
103	            ArrayList<Evaluator> clauses = new ArrayList<>();
104	            if (evaluator instanceof CombiningEvaluator.Or) {
105	                clauses.addAll(((CombiningEvaluator.Or) evaluator).evaluators);
106	            } else {
107	                clauses.add(evaluator);
108	            }
109	            branches = clauses.toArray(new Evaluator[0]);
110	            axes = new char[branches.length];
111	            deep = new boolean[branches.length];
112	            selfScope = new boolean[branches.length];
113	            for (int i = 0; i < branches.length; i++) {
114	                axes[i] = siblingAxis(branches[i]);
115	                deep[i] = axes[i] != 0 && hasChainedCombinator(branches[i]);
116	                // a sibling branch can never match the anchor itself; a descendant branch may when its relationship
117	                // starts (or stays) at the :scope anchor, as in :has(:scope), :has(:scope.x), or :has(p:scope)
118	                selfScope[i] = axes[i] == 0 && ScopeSelector.usesScope(branches[i]);
119	            }
120	        }
121	
122	        @Override public boolean matches(Element root, Element element) {
123	            for (int i = 0; i < branches.length; i++) {
124	                Evaluator branch = branches[i];
125	                if (axes[i] == 0) {
126	                    // a :scope at this level binds to the anchor itself, so a scope-headed branch with no leading
127	                    // combinator may match the anchor (e.g. :has(:scope.x)); every other branch stays descendant-only
128	                    if (selfScope[i] && branch.matches(element, element)) return true;
129	                    if (matchesDescendants(element, branch)) return true;
130	                } else {
131	                    if (matchesFollowingSiblings(element, axes[i], deep[i], branch)) return true;
132	                }
133	            }
134	            return false;
135	        }
136	
137	        /** Match a descendant-only branch (bare or {@code >}) within the anchor, never against the anchor itself. */
138	        private static boolean matchesDescendants(Element anchor, Evaluator branch) {
139	            NodeIterator<Node> it = NodeIterPool.borrow();
140	            it.restart(anchor);
141	            try {
142	                while (it.hasNext()) {
143	                    Node node = it.next();
144	                    if (node == anchor) continue; // don't match self, only descendants
145	                    if (branch.matches(anchor, node)) return true;
146	                }
147	            } finally {
148	                NodeIterPool.release(it);
149	            }
150	            return false;
151	        }
152	
153	        /**
154	         * Match a {@code +}/{@code ~} branch against following element siblings (element nodes only). The anchor is
155	         * supplied as the matching root, so the branch's leading sibling edge (whose left side is the synthetic Root)
156	         * resolves to the anchor: {@code +} is satisfied only by the immediate sibling, {@code ~} by any later one.
157	         * A simple branch ({@code + p.selected}) tests the sibling elements directly, with {@code +} stopping after the
158	         * first. A branch that chains further combinators ({@code + article > img}, {@code + p + img}, {@code ~ p span})
159	         * may match within a sibling's subtree, or -- with chained sibling combinators -- in a later sibling, so every
160	         * following sibling and its subtree is searched; the root-scoped structural evaluators enforce the exact
161	         * adjacency and never walk above the anchor, so the broader search domain cannot mis-match.
162	         */
163	        private static boolean matchesFollowingSiblings(Element anchor, char axis, boolean deep, Evaluator branch) {
164	            Element sibling = anchor.nextElementSibling();
165	            if (!deep) {
166	                while (sibling != null) {
167	                    if (branch.matches(anchor, sibling)) return true;
168	                    if (axis == '+') break; // '+' is the immediate sibling only; '~' may reach a later one
169	                    sibling = sibling.nextElementSibling();
170	                }
171	                return false;
172	            }
173	
174	            NodeIterator<Node> it = NodeIterPool.borrow();
175	            try {
176	                while (sibling != null) {
177	                    it.restart(sibling);
178	                    while (it.hasNext()) {
179	                        Node node = it.next();
180	                        if (branch.matches(anchor, node)) return true;
181	                    }
182	                    sibling = sibling.nextElementSibling();
183	                }
184	            } finally {
185	                NodeIterPool.release(it);
186	            }
187	            return false;
188	        }
189	
190	        @Override
191	        boolean evaluateMatch(Element root, Node node) {
192	            return false; // unused; :has(::comment)) goes via implicit root combinator
193	        }
194	
195	        /**
196	         * Determine a branch's leading sibling axis, if any, by tracing its left-most combinator edge. Only a leading
197	         * {@code +} or {@code ~} is compiled against the synthetic {@link Root} (the anchor): it appears as an
198	         * immediate/general sibling evaluator wrapping {@link Root} at the start of the chain (possibly beneath
199	         * descendant and child edges). An internal sibling combinator references a real selector, not {@link Root},
200	         * and so is scoped to the anchor's descendants rather than the anchor's own siblings.
201	         * @return {@code '+'}, {@code '~'}, or {@code 0} for a descendant-only branch
202	         */
203	        private static char siblingAxis(Evaluator branch) {
204	            Evaluator edge = branch;
205	            while (true) {
206	                if (edge instanceof CombiningEvaluator.And) {
207	                    // the parser places the left-hand structural wrapper (Ancestor/sibling) first in the And
208	                    edge = ((CombiningEvaluator.And) edge).evaluators.get(0);
209	                } else if (edge instanceof ImmediateParentRun) {
210	                    edge = ((ImmediateParentRun) edge).evaluators.get(0);
211	                } else if (edge instanceof Ancestor) {
212	                    edge = ((Ancestor) edge).evaluator;
213	                } else if (edge instanceof ImmediatePreviousSibling) {
214	                    Evaluator left = ((StructuralEvaluator) edge).evaluator;
215	                    if (left instanceof Root || ScopeSelector.isScopeAnchor(left)) return '+';
216	                    edge = left; // a chained sibling combinator; continue to the left-most edge
217	                } else if (edge instanceof PreviousSibling) {
218	                    Evaluator left = ((StructuralEvaluator) edge).evaluator;
219	                    if (left instanceof Root || ScopeSelector.isScopeAnchor(left)) return '~';
220	                    edge = left;
221	                } else {
222	                    return 0; // bare branch, or a leading '>' (a Root)
223	                }
224	            }
225	        }
226	
227	        /**
228	         * Whether a sibling branch chains a further combinator after its leading {@code +}/{@code ~}, such that the
229	         * match target may lie within a sibling's subtree (e.g. {@code + article > img}) rather than being the sibling
230	         * element itself (e.g. {@code + p.selected}). The leading sibling-of-{@link Root} edge is the axis edge and is
231	         * not counted; {@link Is}, {@link Not} and nested {@link Has} evaluate their own contents and are self-contained.
232	         */
233	        private static boolean hasChainedCombinator(Evaluator eval) {
234	            if (eval instanceof Ancestor) return true;
235	            if (eval instanceof ImmediateParentRun) return ((ImmediateParentRun) eval).evaluators.size() > 1;
236	            if (eval instanceof ImmediatePreviousSibling || eval instanceof PreviousSibling) {
237	                Evaluator left = ((StructuralEvaluator) eval).evaluator;
238	                return !(left instanceof Root || ScopeSelector.isScopeAnchor(left)); // leading axis edge wraps the anchor
239	            }
240	            if (eval instanceof CombiningEvaluator) {
241	                for (Evaluator child : ((CombiningEvaluator) eval).evaluators) {
242	                    if (hasChainedCombinator(child)) return true;
243	                }
244	            }
245	            return false; // a plain simple sequence, or a self-contained evaluator (Is, Not, nested Has, etc.)
246	        }
247	
248	        @Override protected int cost() {
249	            return 10 * evaluator.cost();
250	        }
251	
252	        @Override
253	        public String toString() {
254	            return String.format(":has(%s)", evaluator);
255	        }
256	    }
257	
258	    /** Implements the :is(sub-query) pseudo-selector */
259	    static class Is extends StructuralEvaluator {
260	        public Is(Evaluator evaluator) {
261	            super(evaluator);
262	        }
263	
264	        @Override
265	        boolean evaluateMatch(Element root, Node node) {
266	            return evaluator.matches(root, node);
267	        }
268	
269	        @Override protected int cost() {
270	            return 2 + evaluator.cost();
271	        }
272	
273	        @Override
274	        public String toString() {
275	            return String.format(":is(%s)", evaluator);
276	        }
277	    }
278	
279	    static class Not extends StructuralEvaluator {
280	        public Not(Evaluator evaluator) {
281	            super(evaluator);
282	        }
283	
284	        @Override
285	        boolean evaluateMatch(Element root, Node node) {
286	            return !memoMatches(root, node);
287	        }
288	
289	        @Override protected int cost() {
290	            return 2 + evaluator.cost();
291	        }
292	
293	        @Override
294	        public String toString() {
295	            return String.format(":not(%s)", evaluator);
296	        }
297	    }
298	
299	    /**
300	     Any Ancestor (i.e., ascending parent chain.).
301	     */
302	    static class Ancestor extends StructuralEvaluator {
303	        public Ancestor(Evaluator evaluator) {
304	            super(evaluator);
305	        }
306	
307	        @Override
308	        boolean evaluateMatch(Element root, Node node) {
309	            if (root == node)
310	                return false;
311	
312	            for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
313	                if (memoMatches(root, parent))
314	                    return true;
315	                if (parent == root)
316	                    break;
317	            }
318	            return false;
319	        }
320	
321	        @Override
322	        protected int cost() {
323	            return 8 * evaluator.cost(); // probably lower than has(), but still significant, depending on doc and el depth.
324	        }
325	
326	        @Override
327	        public String toString() {
328	            return String.format("%s ", evaluator);
329	        }
330	    }
331	
332	    /**
333	     Holds a list of evaluators for one > two > three immediate parent matches, and the final direct evaluator under
334	     test. To match, these are effectively ANDed together, starting from the last, matching up to the first.
335	     */
336	    static class ImmediateParentRun extends StructuralEvaluator {
337	        final ArrayList<Evaluator> evaluators = new ArrayList<>();
338	        int cost = 2;
339	
340	        public ImmediateParentRun(Evaluator evaluator) {
341	            super(evaluator);
342	            evaluators.add(evaluator);
343	            cost += evaluator.cost();
344	        }
345	
346	        void add(Evaluator evaluator) {
347	            evaluators.add(evaluator);
348	            cost += evaluator.cost();
349	            wantsNodes |= evaluator.wantsNodes();
350	        }
351	
352	        @Override boolean evaluateMatch(Element root, Node node) {
353	            if (node == root)
354	                return false; // cannot match as the second eval (first parent test) would be above the root
355	
356	            for (int i = evaluators.size() -1; i >= 0; --i) {
357	                if (node == null)
358	                    return false;
359	                Evaluator eval = evaluators.get(i);
360	                if (!eval.matches(root, node))
361	                    return false;
362	                node = node.parent();
363	            }
364	            return true;
365	        }
366	
367	        @Override protected int cost() {
368	            return cost;
369	        }
370	
371	        @Override
372	        protected void reset() {
373	            for (Evaluator evaluator : evaluators) {
374	                evaluator.reset();
375	            }
376	            super.reset();
377	        }
378	
379	        @Override
380	        public String toString() {
381	            return StringUtil.join(evaluators, " > ");
382	        }
383	    }
384	
385	    static class PreviousSibling extends StructuralEvaluator {
386	        public PreviousSibling(Evaluator evaluator) {
387	            super(evaluator);
388	        }
389	
390	        // matches any previous sibling, so can be same in Element only or wantsNodes context
391	        @Override boolean evaluateMatch(Element root, Node node) {
392	            if (root == node) return false;
393	
394	            for (Node sib = node.firstSibling(); sib != null; sib = sib.nextSibling()) {
395	                if (sib == node) break;
396	                if (memoMatches(root, sib)) return true;
397	            }
398	
399	            return false;
400	        }
401	
402	        @Override protected int cost() {
403	            return 3 * evaluator.cost();
404	        }
405	
406	        @Override
407	        public String toString() {
408	            return String.format("%s ~ ", evaluator);
409	        }
410	    }
411	
412	    static class ImmediatePreviousSibling extends StructuralEvaluator {
413	        public ImmediatePreviousSibling(Evaluator evaluator) {
414	            super(evaluator);
415	        }
416	
417	        @Override boolean evaluateMatch(Element root, Node node) {
418	            if (root == node) return false;
419	
420	            Node prev = wantsNodes ? node.previousSibling() : node.previousElementSibling();
421	            return prev != null && memoMatches(root, prev);
422	        }
423	
424	        @Override protected int cost() {
425	            return 2 + evaluator.cost();
426	        }
427	
428	        @Override
429	        public String toString() {
430	            return String.format("%s + ", evaluator);
431	        }
432	    }
433	}
