import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;

import java.util.Arrays;

public class Probe {
    static int failures = 0;

    static void check(String name, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        if (!ok) failures++;
        System.out.printf("%-70s %s  actual=%s expected=%s%n", name, ok ? "PASS" : "FAIL", actual, expected);
    }

    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) {
            if (sb.length() > 0) sb.append(',');
            sb.append(e.id());
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // ---- 1. :scope inside of S, scoped select on ul ----
        Document doc = Jsoup.parse(
            "<div id=outer><ul id=ul>" +
            "<li id=a class=r></li><li id=b></li><li id=c class=r></li>" +
            "</ul><p id=p class=r>x</p></div>");
        Element ul = doc.expectFirst("#ul");
        // of S with :scope: .r siblings of the scoped element's children... anchor is ul
        check("scope-in-of: :scope > .r counts", ids(ul.select("li:nth-child(odd of :scope > .r)")), "a,c");
        // :has in of S
        Document d2 = Jsoup.parse("<ul><li id=a><b></b></li><li id=b></li><li id=c><b></b></li></ul>");
        check("has-in-of", ids(d2.select("li:nth-child(2 of li:has(b))")), "c");

        // ---- 2. combinators in filter list (each branch anchored at numbered sibling) ----
        // S = "i x" (descendant combinator): sibling li containing x? descendant is within sibling itself
        Document d3 = Jsoup.parse("<ul>" +
            "<li id=a><x/></li><li id=b><y/></li><li id=c><x/></li></ul>");
        check("descendant combinator in of", ids(d3.select("li:nth-child(2 of li x)").parents("li").isEmpty() ?
            d3.select("li:nth-child(2 of li):nth-child(2)") : d3.select("li:nth-child(2 of li x)")),
            "c"); // placeholder, replaced below

        // Actually: filter "li:has(x)" vs "li x": "li x" as a standalone selector evaluated against sibling:
        // Ancestor check walks parents; root is document. sibling li with x descendant should match.
        check("combinator 'li x' in of S", ids(d3.select("li:nth-child(2 of li x)")), "c");

        // ---- 3. mutations: renumber immediately, same compiled evaluator ----
        Document d4 = Jsoup.parse("<ul><li id=a class=k></li><li id=b class=k></li><li id=c class=k></li></ul>");
        Evaluator ev = Selector.evaluatorOf("li:nth-child(2 of .k)");
        check("before mutation", ids(d4.select(ev)), "b");
        d4.expectFirst("#a").remove();
        check("after remove renumber", ids(d4.select(ev)), "c"); // b now pos1, c pos2
        d4.expectFirst("#b").addClass("k"); // already k; instead remove class from b
        d4.expectFirst("#b").removeClass("k");
        check("after class change", ids(d4.select(ev)), ""); // only c matches filter at pos1
        Document d5 = Jsoup.parse("<ul><li id=x class=k></li><li id=y class=k></li></ul>");
        check("reuse evaluator other doc", ids(d5.select(ev)), "y");

        // ---- 4. error cases ----
        String[] invalid = {
            "li:nth-child(2 of)",
            "li:nth-child(2 of )",
            "li:nth-child( of .p)",
            "li:nth-child(of .p)",
            "li:nth-child(2 of .p",
            "li:nth-child(2 of ..p)",
            "li:nth-child(2 of :bogus(.))",
            "li:nth-child(2 of >)",          // dangling combinator in S
            "li:nth-child(2 of .a >)",       // dangling combinator in S
            "li:nth-child(2 of + .a)",       // leading combinator in of S (should parse? leading > is fine in grammar)
            "li:nth-child(2n+1 of .a,)",     // empty branch
            "li:nth-child(x of .p)",         // illegal coefficient
            "li:nth-child( of)",
            "li:nth-child()",                // missing formula
            "li:nth-child( )",
        };
        for (String q : invalid) {
            boolean threw;
            try { Selector.evaluatorOf(q); threw = false; }
            catch (Selector.SelectorParseException e) { threw = true; }
            check("REJECT: " + q, threw, true);
        }

        // ---- 5. dedup & order with comma branches ----
        Document d6 = Jsoup.parse("<ul>" +
            "<li id=a class=p data-kind=card></li><li id=b class=p data-kind=ad></li>" +
            "<li id=c data-kind=card></li><li id=d class=p data-kind=card></li></ul>");
        check("comma dedup/order", ids(d6.select("li:nth-child(2n+1 of .ready, [data-kind=card])").isEmpty()
            ? d6.select("li:nth-child(2n+1 of .p, [data-kind=card])")
            : d6.select("li:nth-child(2n+1 of .ready, [data-kind=card])")), "a,d");
        // Both branches: .p set = {a,b,d}, card set = {a,c,d}; odd positions per branch:
        // .p: a(pos1), d(pos3); card: a(pos1), d(pos3); merged => a,d

        // ---- 6. non-element nodes don't count ----
        Document d7 = Jsoup.parse("<ul><!-- c --><li id=a></li> x <li id=b></li></ul>");
        check("text/comment ignored nth-of", ids(d7.select("li:nth-child(2 of li)")), "b");
        check("text/comment plain nth", ids(d7.select("li:nth-child(2)")), "b");

        // ---- 7. unchanged semantics w/o of ----
        Document d8 = Jsoup.parse("<ul><li id=a></li><li id=b></li><li id=c></li><li id=d></li></ul>");
        check("plain odd", ids(d8.select("li:nth-child(odd)")), "a,c");
        check("plain 2n+1", ids(d8.select("li:nth-child(2n+1)")), "a,c");
        check("plain nth-last", ids(d8.select("li:nth-last-child(1)")), "d");

        // ---- 8. formula edge: zero matches, negative a, 'n' alone ----
        Document d9 = Jsoup.parse("<ul><li class=p id=a></li><li class=p id=b></li><li class=p id=c></li></ul>");
        check("n alone = all", ids(d9.select("li:nth-child(n of .p)")), "a,b,c");
        check("0 = none", ids(d9.select("li:nth-child(0 of .p)")), "");
        check("5 beyond = none", ids(d9.select("li:nth-child(5 of .p)")), "");
        check("-n+2 first two", ids(d9.select("li:nth-child(-n+2 of .p)")), "a,b");
        check("last -n+2", ids(d9.select("li:nth-last-child(-n+2 of .p)")), "b,c");

        // ---- 9. candidate must be in filtered set AND in outer compound ----
        // span in filter, candidate li: must never match even if index hits
        Document d10 = Jsoup.parse("<ul><span id=s class=q></span><li id=l></li></ul>");
        check("li not in S(span)", ids(d10.select("li:nth-child(1 of span)")), "");

        // ---- 10. multiple parents independently numbered ----
        Document d11 = Jsoup.parse("<ul><li class=p id=a></li><li class=p id=b></li></ul>" +
            "<ul><li class=p id=c></li><li id=z></li><li class=p id=d></li></ul>");
        check("multi parents", ids(d11.select("li:nth-child(2 of .p)")), "b,d");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
    }
}

