        check("compound works", ids(d3.select("li:nth-child(2 of li:has(x))")), "c");
        // descendant selector "li x" matches only x elements, never an li sibling => empty, but must parse
        check("descendant combinator parses, no li match", ids(d3.select("li:nth-child(2 of li x)")), "");
        // leading + combinator in S parses (like select(+ x)), but cannot match from doc root
        check("leading + in S parses", Selector.evaluatorOf("li:nth-child(1 of + li)").toString()
            .contains("of"), true);

