        Document d11 = Jsoup.parse("<ul><li class=p id=a></li><li class=p id=b></li></ul>" +
            "<ul><li class=p id=c></li><li id=z></li><li class=p id=d></li></ul>");
        check("multi parents", ids(d11.select("li:nth-child(2 of .p)")), "b,d");

        // 11. Document-level select root: filter with :scope scoped to the select context, not document
        Document d12 = Jsoup.parse("<div id=d><p id=a class=z></p><p id=b class=z></p></div>");
        Element d = d12.expectFirst("#d");
