        // document select: root is document, :scope matches document; :scope > .z => html? no match
        check("scope at doc root no false hit", ids(d12.select("p:nth-child(1 of :scope > .z)")), "");

        // 12. id/attribute/type filters
        Document d13 = Jsoup.parse("<ul><li id=a data-x=1></li><li id=b data-x=2></li><li id=c data-x=1></li></ul>");
