        check("id filter", ids(d13.select("li:nth-child(1 of #b)")), "b");
        check("type filter", ids(d13.select("li:nth-child(2 of li)")), "b");

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
    }
}

