import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.select.Elements;

public class Probe8 {
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (var e : els) { if (sb.length()>0) sb.append(','); sb.append(e.id()); }
        return sb.toString();
    }
    public static void main(String[] args) {
        // :scope nested inside :has inside of S (binds to has candidate)
        Document d = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li></ul>");
        System.out.println("has(:scope) in of: " + ids(d.select("li:nth-child(2 of li:has(:scope.p), .p)"))); // expect b

        // multiple spaces / tabs before of
        Document d2 = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li></ul>");
        System.out.println("multi-space of: " + ids(d2.select("li:nth-child(2n  of  .p)"))); // expect b

        // XML document
        String xml = "<root><item id='a' class='p'/><item id='b'/><item id='c' class='p'/></root>";
        Document x = Jsoup.parse(xml, "", Parser.xmlParser());
        System.out.println("xml nth-of: " + ids(x.select("item:nth-child(1 of .p)")));  // expect a
        System.out.println("xml nth-last-of: " + ids(x.select("item:nth-last-child(1 of .p)"))); // expect c

        // direct Element.select on a li (filter evaluated relative to that root; siblings are outside)
        Document d3 = Jsoup.parse("<ul><li id=a class=p></li><li id=b class=p></li><li id=c class=p></li></ul>");
        System.out.println("select on li#b: " + ids(d3.expectFirst("#b").select(":nth-child(2 of .p)"))); // descendants only -> none
    }
}
